        'ひぐれとうのエビ油天ぷら：エビの油で揚げ、旨味を大きく高めた一品',
        'ひぐれとうの和え物：さっと湯通ししたつぼみを調味料で和えた一品',
        'ひぐれとうの吸い物：出汁につぼみを浮かべ、香りと甘味を楽しむ汁物',
